//! Compatibility tests against the fixtures generated by the Go implementation.

use hickory_proto::rr::{Record, RecordType};
use pm_config::Config;
use pm_resolver::rr_text::{format_rr, parse_rr};
use pm_resolver::settings::register_options;
use pm_resolver::{NameRecord, RRCache};
use serde_json::Value;

fn fixture(name: &str) -> Value {
    let path = format!("{}/../fixtures/m0/{name}", env!("CARGO_MANIFEST_DIR"));
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn go_json(value: &Value) -> String {
    String::from_utf8(pm_dsd::gojson::to_vec(value).unwrap()).unwrap()
}

#[test]
fn dns_options_match_go_export() {
    let expected = fixture("resolver_options.json");
    let expected = expected.as_array().unwrap();

    let config = Config::new();
    register_options(&config).unwrap();
    let ours: Vec<_> = config
        .export_options()
        .into_iter()
        .filter(|o| o.key.starts_with("dns/"))
        .collect();

    assert_eq!(ours.len(), expected.len());
    assert_eq!(expected.len(), 7);
    for (ours, expected) in ours.iter().zip(expected) {
        assert_eq!(
            go_json(&serde_json::to_value(ours).unwrap()),
            go_json(expected),
            "option {}",
            ours.key
        );
    }
}

#[test]
fn nameserver_validation() {
    let config = Config::new();
    register_options(&config).unwrap();
    assert!(config
        .set_config_option(
            "dns/nameservers",
            serde_json::json!(["dot://dns.example?ip=192.0.2.1&name=x", "dns://192.0.2.2"])
        )
        .is_ok());
    assert!(config
        .set_config_option("dns/nameservers", serde_json::json!(["ftp://192.0.2.1"]))
        .is_err());
    assert!(config
        .set_config_option("dns/nameservers", serde_json::json!(["dns://not-an-ip"]))
        .is_err());
    assert!(config
        .set_config_option("dns/nameserverRetryRate", serde_json::json!(5))
        .is_err());
    assert!(config
        .set_config_option("dns/nameserverRetryRate", serde_json::json!(60))
        .is_ok());
}

/// Types with a presentation form in Rust; Go prints the same text for them.
const TEXT_TYPES: &[&str] = &["A", "AAAA", "CNAME", "NS", "PTR", "MX", "TXT", "SOA", "SRV"];

#[test]
fn rr_text_matches_go() {
    let mut text_cases = 0;
    for case in fixture("resolver.json")["rr_texts"].as_array().unwrap() {
        let input = case["in"].as_str().unwrap();
        let Some(out) = case["out"].as_str() else {
            // Go rejects the input as well.
            assert!(parse_rr(input).is_err(), "{input}");
            continue;
        };
        let record_type = case["type"].as_str().unwrap();
        if TEXT_TYPES.contains(&record_type) && !input.contains("\\#") {
            let parsed = parse_rr(input).unwrap_or_else(|e| panic!("{input}: {e}"));
            assert_eq!(format_rr(&parsed).as_deref(), Some(out), "{input}");
            // Go's own output is read back identically.
            let again = parse_rr(out).unwrap();
            assert_eq!(format_rr(&again).as_deref(), Some(out), "{out}");
            text_cases += 1;
        } else if !input.contains("\\#") {
            // Other types are only supported in the generic form.
            assert!(parse_rr(input).is_err(), "{input}");
        }
    }
    assert!(text_cases >= 12, "{text_cases}");
}

fn rrs(texts: &[&str]) -> Vec<Record> {
    texts.iter().map(|t| parse_rr(t).unwrap()).collect()
}

fn cache_for(name: &str) -> RRCache {
    let resolver: Value = serde_json::json!({
        "Name": "Cloudflare", "Type": "dot", "Source": "config", "IP": "1.1.1.2",
        "Domain": "cloudflare-dns.com", "IPScope": 4, "Port": 853
    });
    let system: Value = serde_json::json!({
        "Name": "", "Type": "dns", "Source": "system", "IP": "192.168.1.1",
        "Domain": "", "IPScope": 3, "Port": 53
    });
    let mut cache = RRCache {
        domain: String::new(),
        question: RecordType::A,
        rcode: 0,
        answer: vec![],
        ns: vec![],
        extra: vec![],
        expires: 0,
        resolver: None,
        served_from_cache: false,
        requesting_new: false,
        is_backup: false,
        filtered: false,
        filtered_entries: vec![],
        modified: 0,
    };
    match name {
        "a_cname_aaaa" => {
            cache.domain = "example.com.".into();
            cache.answer = rrs(&[
                "example.com. 17 IN CNAME www.example.net.",
                "www.example.net. 17 IN A 192.0.2.1",
                "www.example.net. 17 IN AAAA 2001:db8::1",
            ]);
            cache.extra = rrs(&["example.com. 17 IN TXT \"extra \\\"quoted\\\"\""]);
            cache.expires = 1_700_000_060;
            cache.resolver = Some(serde_json::from_value(resolver).unwrap());
        }
        "nxdomain_soa" => {
            cache.domain = "nothing.example.com.".into();
            cache.question = RecordType::AAAA;
            cache.rcode = 3;
            cache.ns = rrs(&["example.com. 17 IN SOA ns1.example.com. hostmaster.example.com. 2024010101 7200 3600 1209600 300"]);
            cache.expires = 1_700_000_010;
            cache.resolver = Some(serde_json::from_value(system).unwrap());
        }
        "empty_sections" => {
            cache.domain = "empty.example.com.".into();
            cache.question = RecordType::MX;
            cache.expires = 1_700_000_060;
            cache.resolver = Some(serde_json::from_value(resolver).unwrap());
        }
        other => panic!("unknown sample {other}"),
    }
    cache
}

#[test]
fn name_records_match_go_bytes() {
    let fx = fixture("resolver.json");
    let cases = fx["name_records"].as_array().unwrap();
    assert_eq!(cases.len(), 3);
    for case in cases {
        let name = case["name"].as_str().unwrap();
        let expected = case["json"].as_str().unwrap();

        let record = cache_for(name).to_name_record().unwrap();
        assert_eq!(record.key(), case["key"].as_str().unwrap(), "{name}");
        assert_eq!(
            String::from_utf8(record.to_json().unwrap()).unwrap(),
            expected,
            "{name}"
        );

        // The Go JSON is read back and written identically.
        let read: NameRecord = serde_json::from_str(expected).unwrap();
        assert!(read.is_valid());
        assert_eq!(read, record, "{name}");
        let back = RRCache::from_name_record(&read, record_type_of(&read), 0).unwrap();
        assert_eq!(
            String::from_utf8(back.to_name_record().unwrap().to_json().unwrap()).unwrap(),
            expected,
            "{name}"
        );
    }
}

fn record_type_of(record: &NameRecord) -> RecordType {
    record.question.parse::<RecordType>().unwrap()
}

/// Writes the Rust-written records so that Go can be asked to read them
/// (`go run ./tools/rust-fixtures -verify-namerecord <file>`).
#[test]
#[ignore = "helper: exports Rust-written records for `rust-fixtures -verify-namerecord` when PM_RESOLVER_EXPORT_DIR is set"]
fn rust_written_records_for_go_verification() {
    if let Ok(dir) = std::env::var("PM_RESOLVER_EXPORT_DIR") {
        for name in ["a_cname_aaaa", "nxdomain_soa", "empty_sections"] {
            let record = cache_for(name).to_name_record().unwrap();
            std::fs::write(format!("{dir}/{name}.json"), record.to_json().unwrap()).unwrap();
        }
        // Types with a generic form only.
        let mut cache = cache_for("a_cname_aaaa");
        cache.answer = rrs(&[
            "example.com. 17 IN TYPE65 \\# 13 00010000010006026832026833",
            "example.com. 17 IN TXT \"a\\200b\" \"tab\\009\"",
            "example.com. 17 IN MX 10 mail.example.com.",
        ]);
        std::fs::write(
            format!("{dir}/generic.json"),
            cache.to_name_record().unwrap().to_json().unwrap(),
        )
        .unwrap();
    }
}
